/**
 * @agrorende/motion: original Lottie animations for the landing site, the admin web app and
 * the mobile app. The JSON files in `lottie/` are generated by `pnpm build:lottie` from the
 * builders in `src/animations/`; never edit them by hand.
 */
import type { LottieJson } from "./lottie/types";
import type { AnimationId } from "./meta";
import welcomeJson from "../lottie/welcome.json";
import reportOfflineJson from "../lottie/report-offline.json";
import flowLoopJson from "../lottie/flow-loop.json";
import machineCostJson from "../lottie/machine-cost.json";
import officeLiveJson from "../lottie/office-live.json";
import inviteTeamJson from "../lottie/invite-team.json";
import firstMachineJson from "../lottie/first-machine.json";
import firstWorkOrderJson from "../lottie/first-work-order.json";
import signatureJson from "../lottie/signature.json";
import successJson from "../lottie/success.json";
import emptyJson from "../lottie/empty.json";
import savedOnPhoneJson from "../lottie/saved-on-phone.json";
import rentalHandoverJson from "../lottie/rental-handover.json";
import loadingJson from "../lottie/loading.json";

export { ANIMATION_IDS, motionMeta, type AnimationId, type MotionMeta } from "./meta";
export type { LottieJson } from "./lottie/types";
export { loadAnimation } from "./lazy";

/**
 * Every animation, imported eagerly. Metro needs static requires, so the mobile app uses this
 * record; web surfaces should import `loadAnimation` from `@agrorende/motion/lazy` to keep the JSON
 * out of the shared bundle.
 */
export const animations: Record<AnimationId, LottieJson> = {
  welcome: welcomeJson,
  "report-offline": reportOfflineJson,
  "flow-loop": flowLoopJson,
  "machine-cost": machineCostJson,
  "office-live": officeLiveJson,
  "invite-team": inviteTeamJson,
  "first-machine": firstMachineJson,
  "first-work-order": firstWorkOrderJson,
  signature: signatureJson,
  success: successJson,
  empty: emptyJson,
  "saved-on-phone": savedOnPhoneJson,
  "rental-handover": rentalHandoverJson,
  loading: loadingJson,
};
